*{box-sizing:border-box;margin:0;padding:0}
html,body{width:100%;height:100%;background:#000;overflow:hidden}
body{display:flex;align-items:center;justify-content:center;font-family:Georgia,serif}
.space{position:relative;width:100vw;height:100vh;display:flex;align-items:center;justify-content:center;background:#000}
.screen{position:absolute;width:min(100vw,112vh);background-position:center;background-repeat:no-repeat;background-size:100% 100%;transition:opacity .65s,transform .65s}
#intro{aspect-ratio:1678/937;background-image:url("data:image/png;base64,")}
#lobby{aspect-ratio:1262/638;background-image:url("data:image/png;base64,");opacity:0;pointer-events:none;transform:scale(1.015)}
.hidden{opacity:0!important;pointer-events:none!important}

.entry-mask{position:absolute;left:32%;top:72%;width:36%;height:22%;z-index:15;pointer-events:none;background:radial-gradient(ellipse at center,rgba(0,0,0,.98) 0%,rgba(0,0,0,.92) 45%,rgba(0,0,0,.45) 72%,rgba(0,0,0,0) 100%);}
.hotspot{position:absolute;border:0;background:transparent;cursor:pointer;z-index:20}



/* Entrada */
.enter{left:44%;top:82%;width:12%;height:7%;display:flex;align-items:center;justify-content:center;color:#eee;background:rgba(0,0,0,.35);border:1px solid rgba(255,255,255,.22);border-radius:5px;font:600 12px Arial,sans-serif;letter-spacing:3px;text-shadow:0 0 8px rgba(255,255,255,.25);transition:.25s;z-index:30}
.enter:hover{color:#9dffb5;border-color:rgba(80,255,120,.65);background:rgba(30,90,45,.18);box-shadow:0 0 14px rgba(80,255,120,.22)}
.enter:focus,.enter:focus-visible{outline:none}

/* Lobby: coordenadas sobre la segunda imagen */
.left-menu{left:0;top:15%;width:18%;height:72%}
.profile{left:7%;top:0;width:11%;height:14%}
.home{left:0;top:15%;width:18%;height:15%}
.heroes{left:0;top:40%;width:18%;height:14%}
.collection{left:0;top:55%;width:18%;height:14%}
.events{left:0;top:70%;width:18%;height:15%}

.friends{right:0;top:15%;width:24%;height:39%}
.music{right:0;bottom:18%;width:24%;height:15%}
.avt{right:0;bottom:29%;width:24%;height:19%}
.start{left:37%;bottom:4%;width:26%;height:13%}


/* Paneles reales */
.panel{position:absolute;z-index:40;left:18%;right:24%;top:14%;bottom:12%;background:rgba(5,9,8,.96);border:1px solid rgba(108,255,145,.45);box-shadow:0 0 35px rgba(0,0,0,.8);padding:28px;color:#eee;display:none}
.panel.open{display:block}
.panel h2{font-size:22px;letter-spacing:6px;color:#7dff9d;margin-bottom:8px}
.panel p{font:13px Arial,sans-serif;color:#aaa;line-height:1.6}
.close{position:absolute;right:14px;top:10px;background:none;border:0;color:#aaa;font-size:22px;cursor:pointer}
.list{margin-top:22px;display:grid;gap:10px;font:13px Arial,sans-serif}
.item{padding:12px;border-bottom:1px solid rgba(255,255,255,.1);color:#ccc}
.item strong{color:#7dff9d}
#toast{position:absolute;left:50%;bottom:15%;transform:translateX(-50%);z-index:60;background:rgba(5,10,8,.94);border:1px solid rgba(110,255,145,.4);padding:10px 18px;color:#bfffd0;font:11px Arial,sans-serif;letter-spacing:2px;opacity:0;transition:.25s;pointer-events:none}
#toast.show{opacity:1}

@media(max-width:700px){
 .screen{width:100vw}
 .panel{left:10%;right:10%;top:15%;bottom:15%;padding:18px}
 .panel h2{font-size:16px}
 .panel p,.list{font-size:11px}
}

/* Revelado suave de Doom al mover el cursor */
.intro-reveal{position:absolute;inset:0;z-index:8;pointer-events:none;background-image:url("data:image/png;base64,");background-position:center;background-repeat:no-repeat;background-size:100% 100%;opacity:0;transition:opacity .28s ease;mask-image:radial-gradient(circle 240px at var(--mx,50%) var(--my,50%),rgba(0,0,0,1) 0%,rgba(0,0,0,.82) 45%,rgba(0,0,0,0) 100%);-webkit-mask-image:radial-gradient(circle 240px at var(--mx,50%) var(--my,50%),rgba(0,0,0,1) 0%,rgba(0,0,0,.82) 45%,rgba(0,0,0,0) 100%);filter:brightness(1.65) contrast(1.08);}
#intro:hover .intro-reveal{opacity:.9}

#heroesGallery {
  position:fixed; inset:0; z-index:999;
  display:none; align-items:center; justify-content:center;
  background:rgba(0,0,0,.84);
  backdrop-filter:blur(7px);
}
#heroesGallery.open { display:flex; }
#heroesGallery .heroes-frame {
  position:relative;
  width:min(96vw,1500px);
  max-height:92vh;
  aspect-ratio:1536/1024;
  background:#020403 url("data:image/png;base64,") center/cover no-repeat;
  border:1px solid rgba(120,255,170,.16);
  box-shadow:0 0 70px rgba(60,255,130,.14);
  overflow:hidden;
}
#heroesGallery .heroes-close {
  position:absolute; top:14px; right:16px; z-index:5;
  width:34px; height:34px; border:0; border-radius:50%;
  background:rgba(0,0,0,.55); color:#ddd;
  font-size:21px; line-height:34px; cursor:pointer;
}
#heroesGallery .heroes-close:hover { color:#72ff9d; }